            }
            $result->free();
        }
        $categoryRandomize = [];
        if ($r = $db->query("SELECT category, randomize FROM twitch_alert_category_settings")) {
            while ($row = $r->fetch_assoc()) {
                $categoryRandomize[$row['category']] = (int)$row['randomize'];
            }
            $r->free();
        }
        require_once '/var/www/dashboard/includes/file_paths.php';
        $channelPointRewards = [];
        if ($rewardStmt = $db->query("SELECT reward_id, reward_title, reward_cost FROM channel_point_rewards ORDER BY CONVERT(reward_cost, UNSIGNED) ASC")) {
            $channelPointRewards = $rewardStmt->fetch_all(MYSQLI_ASSOC);
            $rewardStmt->free();
        }
        $libraryImageExts = ['png', 'jpg', 'jpeg', 'gif', 'webm'];
        $librarySoundExts = ['mp3'];
        $libraryImages = [];
        $librarySounds = [];
        if (isset($media_path) && is_string($media_path) && $media_path !== '' && is_dir($media_path)) {
            // Media library folders are one level deep (managed on media.php); nested files are listed as "folder/file.ext".
            $libraryEntries = [];
            foreach (scandir($media_path) as $entry) {
                if ($entry === '.' || $entry === '..') continue;
                $full = $media_path . '/' . $entry;
                if (is_file($full)) {
                    $libraryEntries[] = $entry;
                } elseif (is_dir($full)) {
                    foreach (scandir($full) as $sub) {
                        if ($sub === '.' || $sub === '..') continue;
                        if (is_file($full . '/' . $sub)) $libraryEntries[] = $entry . '/' . $sub;
                    }
                }
            }
            foreach ($libraryEntries as $f) {
                $ext = strtolower(pathinfo($f, PATHINFO_EXTENSION));
                if (in_array($ext, $libraryImageExts, true)) $libraryImages[] = $f;
                elseif (in_array($ext, $librarySoundExts, true)) $librarySounds[] = $f;
            }
            sort($libraryImages, SORT_STRING | SORT_FLAG_CASE);
            sort($librarySounds, SORT_STRING | SORT_FLAG_CASE);
        }
        // Live tests play a sound and video the streamer has mapped, the same files the bot sends.
        $testMedia = ['sound' => null, 'video' => null];
        try {
            if ($r = $db->query("SELECT sound_mapping FROM sound_alerts WHERE sound_mapping IS NOT NULL AND sound_mapping <> '' ORDER BY reward_id LIMIT 1")) {
                $testRow = $r->fetch_row();
                $testMedia['sound'] = $testRow ? $testRow[0] : null;
            }
            if ($r = $db->query("SELECT video_mapping FROM video_alerts WHERE video_mapping IS NOT NULL AND video_mapping <> '' ORDER BY reward_id LIMIT 1")) {
                $testRow = $r->fetch_row();
                $testMedia['video'] = $testRow ? $testRow[0] : null;
            }
        } catch (mysqli_sql_exception $e) {
            $testMedia = ['sound' => null, 'video' => null];
        }
        // The TTS test speaks in the streamer's saved voice.
        $testTtsVoice = null;
        try {
            if ($r = $db->query("SELECT voice, language, style, expressive_voice FROM tts_settings LIMIT 1")) {
                $testTtsVoice = $r->fetch_assoc() ?: null;
            }
        } catch (mysqli_sql_exception $e) {
            $testTtsVoice = null;
        }
        echo json_encode([
            'success' => true,
            'alerts' => empty($allAlerts) ? new stdClass() : $allAlerts,
            'categoryRandomize' => empty($categoryRandomize) ? new stdClass() : $categoryRandomize,
            'libraryImages' => $libraryImages,
            'librarySounds' => $librarySounds,
            'channelPointRewards' => array_values($channelPointRewards),
            'testMedia' => $testMedia,
            'testTtsVoice' => $testTtsVoice,
        ]);
    } catch (mysqli_sql_exception $e) {
        http_response_code(500);
        echo json_encode(['success' => false, 'error' => $e->getMessage()]);
    }
    exit();
}

$stmt = $db->prepare("SELECT timezone FROM profile");
$stmt->execute();
$result = $stmt->get_result();
$channelData = $result->fetch_assoc();
$timezone = $channelData['timezone'] ?? 'UTC';
$stmt->close();
date_default_timezone_set($timezone);

// How many Specter Alerts pages are connected on this channel's key. More than one
// means a stray OBS source (other scene, hidden source, browser tab) is also rendering.
if (($_GET['ajax_action'] ?? '') === 'overlay_instances') {
    header('Content-Type: application/json');
    include_once '/var/www/config/admin_actions.php';
    $clientsUrl = 'https://websocket.botofthespecter.com/clients';
    if (!empty($admin_key)) {
        $clientsUrl .= '?admin_key=' . urlencode($admin_key);
    }
    $ctx = stream_context_create(['http' => ['timeout' => 5, 'ignore_errors' => true]]);
    $raw = @file_get_contents($clientsUrl, false, $ctx);
    $clientsData = $raw ? json_decode($raw, true) : null;
    if (!is_array($clientsData) || !isset($clientsData['clients']) || !is_array($clientsData['clients'])) {
        echo json_encode(['success' => false]);
        exit();
    }
    $count = 0;
    foreach ($clientsData['clients'][$api_key] ?? [] as $client) {
        if (($client['name'] ?? '') === 'Overlay - Twitch Alerts') {
            $count++;
        }
    }
    echo json_encode(['success' => true, 'count' => $count]);
    exit();
}

// Handle AJAX requests
if ($_SERVER['REQUEST_METHOD'] === 'POST' && !empty($_SERVER['HTTP_X_REQUESTED_WITH']) && strtolower($_SERVER['HTTP_X_REQUESTED_WITH']) === 'xmlhttprequest') {
    header('Content-Type: application/json');
    $action = $_POST['action'] ?? '';
    if ($action === 'set_alert_canvas') {
        $allowedCanvas = ['1280x720' => 1.5, '1920x1080' => 1, '2560x1440' => 0.75];
        $canvas = $_POST['canvas'] ?? '1920x1080';
        if (!isset($allowedCanvas[$canvas])) {
            $canvas = '1920x1080';
        }
        $stmt = $db->prepare("INSERT INTO twitch_alert_display (id, canvas) VALUES (1, ?) ON DUPLICATE KEY UPDATE canvas = VALUES(canvas)");
        $stmt->bind_param('s', $canvas);
        $ok = $stmt->execute();
        $stmt->close();
        echo json_encode(['success' => (bool) $ok, 'scale' => $allowedCanvas[$canvas]]);
        exit;
    }
    if ($action === 'save_alert') {
        $id = intval($_POST['id'] ?? 0);
        if ($id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid alert ID.']);
            exit;
        }
        $stmt = $db->prepare("UPDATE twitch_alerts SET
            variant_name = ?, enabled = ?, alert_condition = ?,
            duration = ?, animation_in = ?, animation_out = ?,
            animation_in_duration = ?, animation_out_duration = ?,
            layout_preset = ?, bg_color = ?, bg_opacity = ?,
            padding = ?, gap = ?, rounded_corners = ?, drop_shadow = ?,
            message_template = ?, font_family = ?, font_weight = ?, font_size = ?,
            text_alignment = ?, text_vertical_alignment = ?,
            text_color = ?, accent_color = ?, text_drop_shadow = ?, tts_enabled = ?,
            alert_image = ?, image_scale = ?, image_volume = ?,
            alert_sound = ?, sound_volume = ?,
            celebration_enabled = ?, celebration_effect = ?, celebration_intensity = ?, celebration_area = ?,
            screen_position = ?, position_x = ?, position_y = ?
            WHERE id = ?");
        $variant_name = $_POST['variant_name'] ?? '';
        $enabled = intval($_POST['enabled'] ?? 1);
        $alert_condition = $_POST['alert_condition'] ?? null;
        $duration = intval($_POST['duration'] ?? 8);
        $animation_in = $_POST['animation_in'] ?? 'fadeIn';
        $animation_out = $_POST['animation_out'] ?? 'fadeOut';
        $animation_in_duration = floatval($_POST['animation_in_duration'] ?? 1.0);
        $animation_out_duration = floatval($_POST['animation_out_duration'] ?? 1.0);
        $layout_preset = $_POST['layout_preset'] ?? 'above';
        $bg_color = $_POST['bg_color'] ?? '#FFFFFF';
        $bg_opacity = intval($_POST['bg_opacity'] ?? 0);
        $padding = intval($_POST['padding'] ?? 16);
        $gap = intval($_POST['gap'] ?? 16);
        $rounded_corners = intval($_POST['rounded_corners'] ?? 1);
        $drop_shadow = intval($_POST['drop_shadow'] ?? 1);
        $existingLookup = $db->prepare("SELECT alert_category, message_template FROM twitch_alerts WHERE id = ?");
        $existingLookup->bind_param('i', $id);
        $existingLookup->execute();
        $existingAlert = $existingLookup->get_result()->fetch_assoc();
        $existingLookup->close();
        if (!$existingAlert) {
            $stmt->close();
            echo json_encode(['success' => false, 'message' => 'Invalid alert ID.']);
            exit;
        }
        $existingAlertCategory = $existingAlert['alert_category'];
        $existingAlertTemplate = $existingAlert['message_template'];
        $message_template = $_POST['message_template'] ?? '';
        if (in_array($existingAlertCategory, $fixedMessageCategories, true) && trim($message_template) === '') {
            $keptTemplate = trim((string) ($existingAlertTemplate ?? ''));
            $message_template = $keptTemplate !== ''
                ? $existingAlertTemplate
                : alerts_default_template($existingAlertCategory, $defaultAlerts, $adBreakSeedMessage);
        }
        $font_family = $_POST['font_family'] ?? 'Roboto';
        $font_weight = $_POST['font_weight'] ?? 'Semi-Bold';
        $font_size = intval($_POST['font_size'] ?? 24);
        $text_alignment = $_POST['text_alignment'] ?? 'center';
        $text_vertical_alignment = $_POST['text_vertical_alignment'] ?? 'center';
        $text_color = $_POST['text_color'] ?? '#FFFFFF';
        $accent_color = $_POST['accent_color'] ?? '#7C5CBF';
        // Ad break colour must be #RRGGBB, otherwise keep the yellow default
        $ad_color = (string) ($_POST['ad_color'] ?? '#F5C518');
        if (!preg_match('/^#[0-9A-Fa-f]{6}$/', $ad_color)) {
            $ad_color = '#F5C518';
        }
        $text_drop_shadow = intval($_POST['text_drop_shadow'] ?? 1);
        $tts_enabled = intval($_POST['tts_enabled'] ?? 0);
        $alert_image = $_POST['alert_image'] ?? null;
        $image_scale = intval($_POST['image_scale'] ?? 100);
        $image_volume = intval($_POST['image_volume'] ?? 0);
        $alert_sound = $_POST['alert_sound'] ?? null;
        $sound_volume = intval($_POST['sound_volume'] ?? 50);
        $celebration_enabled = intval($_POST['celebration_enabled'] ?? 0);
        $celebration_effect = $_POST['celebration_effect'] ?? 'fireworks';
        $celebration_intensity = $_POST['celebration_intensity'] ?? 'light';
        $celebration_area = $_POST['celebration_area'] ?? 'full';
        $screen_position = $_POST['screen_position'] ?? null;
        // Drag-to-place coordinates: box top-left as a 0-100 percentage of the 16:9
        // canvas. Clamped here so a bad payload can't push a box off-screen.
        $position_x = max(0, min(100, floatval($_POST['position_x'] ?? 0)));
        $position_y = max(0, min(100, floatval($_POST['position_y'] ?? 0)));
        // Type string realigned to the real column types: 'd' for the two DECIMAL
        // animation durations (previously 'i', which truncated fractional seconds),
        // 'screen_position' (s) plus the two DECIMAL drag coordinates (d, d) appended
        // before the trailing WHERE id (i).
        $stmt->bind_param('sisissddssiiiiisssissssiisiisiissssddi',
            $variant_name, $enabled, $alert_condition,
            $duration, $animation_in, $animation_out,
            $animation_in_duration, $animation_out_duration,
            $layout_preset, $bg_color, $bg_opacity,
            $padding, $gap, $rounded_corners, $drop_shadow,
            $message_template, $font_family, $font_weight, $font_size,
            $text_alignment, $text_vertical_alignment,
            $text_color, $accent_color, $text_drop_shadow, $tts_enabled,
            $alert_image, $image_scale, $image_volume,
            $alert_sound, $sound_volume,
            $celebration_enabled, $celebration_effect, $celebration_intensity, $celebration_area,
            $screen_position, $position_x, $position_y,
            $id
        );
        if ($stmt->execute()) {
        if ($existingAlertCategory === 'ad_break') {
            // Saved separately so a channel whose ad_color column isn't migrated yet still saves
            try {
                $adColorStmt = $db->prepare("UPDATE twitch_alerts SET ad_color = ? WHERE id = ?");
                if ($adColorStmt) {
                    $adColorStmt->bind_param('si', $ad_color, $id);
                    $adColorStmt->execute();
                    $adColorStmt->close();
                }
            } catch (Throwable $ignored) {
            }
        }
            echo json_encode(['success' => true, 'message' => 'Variant saved.']);
        } else {
            echo json_encode(['success' => false, 'message' => 'Failed to save: ' . $stmt->error]);
        }
        $stmt->close();
        exit;
    }
    if ($action === 'toggle_alert') {
        $id = intval($_POST['id'] ?? 0);
        $enabled = intval($_POST['enabled'] ?? 0);
        $stmt = $db->prepare("UPDATE twitch_alerts SET enabled = ? WHERE id = ?");
        $stmt->bind_param('ii', $enabled, $id);
        $stmt->execute();
        $stmt->close();
        echo json_encode(['success' => true]);
        exit;
    }
    if ($action === 'create_variant') {
        $category = $_POST['category'] ?? '';
        if ($category === '') {
            echo json_encode(['success' => false, 'message' => 'Category required.']);
            exit;
        }
        if (isset($variantLimits[$category])) {
            $capStmt = $db->prepare("SELECT COUNT(*) AS cnt FROM twitch_alerts WHERE alert_category = ?");
            $capStmt->bind_param('s', $category);
            $capStmt->execute();
            $capCnt = (int)$capStmt->get_result()->fetch_assoc()['cnt'];
            $capStmt->close();
            if ($capCnt >= $variantLimits[$category]) {
                echo json_encode(['success' => false, 'message' => 'This category only supports ' . $variantLimits[$category] . ' variant' . ($variantLimits[$category] === 1 ? '' : 's') . '.']);
                exit;
            }
        }
        // Pick a name that doesn't collide with siblings
        $base = 'New variant';
        $name = $base;
        $existingStmt = $db->prepare("SELECT variant_name FROM twitch_alerts WHERE alert_category = ?");
        $existingStmt->bind_param('s', $category);
        $existingStmt->execute();
        $existingNames = [];
        $res = $existingStmt->get_result();
        while ($row = $res->fetch_assoc()) {
            $existingNames[$row['variant_name']] = true;
        }
        $existingStmt->close();
        $i = 2;
        while (isset($existingNames[$name])) {
            $name = "$base $i";
            $i++;
        }
        // Next variant_index for this category
        $idxRes = $db->query("SELECT COALESCE(MAX(variant_index), -1) + 1 AS next_idx FROM twitch_alerts WHERE alert_category = " . "'" . $db->real_escape_string($category) . "'");
        $nextIdx = (int)$idxRes->fetch_assoc()['next_idx'];
        // Starts disabled: an unconfigured catch-all would otherwise take over the category on the overlay.
        $insStmt = $db->prepare("INSERT INTO twitch_alerts (alert_category, variant_name, variant_index, enabled, message_template) VALUES (?, ?, ?, 0, ?)");
        $tpl = alerts_default_template($category, $defaultAlerts, $adBreakSeedMessage);
        $insStmt->bind_param('ssis', $category, $name, $nextIdx, $tpl);
        if ($insStmt->execute()) {
            $newId = $insStmt->insert_id;
            $insStmt->close();
            $row = $db->query("SELECT * FROM twitch_alerts WHERE id = $newId")->fetch_assoc();
            echo json_encode(['success' => true, 'variant' => $row]);
        } else {
            echo json_encode(['success' => false, 'message' => 'Failed to create variant: ' . $insStmt->error]);
            $insStmt->close();
        }
        exit;
    }
    if ($action === 'delete_variant') {
        $id = intval($_POST['id'] ?? 0);
        if ($id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid variant ID.']);
            exit;
        }
        $stmt = $db->prepare("DELETE FROM twitch_alerts WHERE id = ?");
        $stmt->bind_param('i', $id);
        $stmt->execute();
        $stmt->close();
        echo json_encode(['success' => true, 'message' => 'Variant deleted.']);
        exit;
    }
    if ($action === 'set_category_randomize') {
        $category = $_POST['category'] ?? '';
        $randomize = intval($_POST['randomize'] ?? 0) ? 1 : 0;
        if ($category === '') {
            echo json_encode(['success' => false, 'message' => 'Category required.']);
            exit;
        }
        $stmt = $db->prepare("INSERT INTO twitch_alert_category_settings (category, randomize) VALUES (?, ?) ON DUPLICATE KEY UPDATE randomize = VALUES(randomize)");
        $stmt->bind_param('si', $category, $randomize);
        $stmt->execute();
        $stmt->close();
        echo json_encode(['success' => true]);
        exit;
    }
    if ($action === 'upload_alert_media') {
        require_once '/var/www/dashboard/includes/upload_helpers.php';
        include '/var/www/dashboard/includes/storage_used.php';
        if (!isset($_FILES['media_file'])) {
            echo json_encode(['success' => false, 'message' => 'No file uploaded.']);
            exit;
        }
        $file = $_FILES['media_file'];
        if (($file['error'] ?? UPLOAD_ERR_NO_FILE) !== UPLOAD_ERR_OK) {
            echo json_encode(['success' => false, 'message' => 'Upload failed.']);
            exit;
        }
        if (!is_uploaded_file($file['tmp_name'] ?? '')) {
            echo json_encode(['success' => false, 'message' => 'Invalid upload.']);
            exit;
        }
        $allowedExts = ['webm', 'gif', 'png', 'jpg', 'jpeg', 'mp3'];
        $ext = strtolower(pathinfo($file['name'], PATHINFO_EXTENSION));
        if (!in_array($ext, $allowedExts, true)) {
            echo json_encode(['success' => false, 'message' => 'Invalid file type. Allowed: ' . implode(', ', $allowedExts)]);
            exit;
        }
        if (!upload_validate_extension_and_mime($file['tmp_name'], $ext, $allowedExts)) {
            echo json_encode(['success' => false, 'message' => 'File contents do not match the declared file type.']);
            exit;
        }
        $remaining = $max_storage_size - $current_storage_used;
        if ($file['size'] > $remaining) {
            echo json_encode(['success' => false, 'message' => 'Storage limit exceeded.']);
            exit;
        }
        if (!is_dir($media_path)) {
            mkdir($media_path, 0755, true);
        }
        $safeName = upload_sanitize_filename($file['name'], $ext);
        $target = upload_unique_target($media_path, $safeName);
        if (move_uploaded_file($file['tmp_name'], $target['path'])) {
            echo json_encode(['success' => true, 'filename' => $target['name'], 'message' => 'File uploaded.']);
        } else {
            echo json_encode(['success' => false, 'message' => 'Upload failed.']);
        }
        exit;
    }
    if ($action === 'generate_alert_sound') {
        require_once '/var/www/dashboard/includes/upload_helpers.php';
        include '/var/www/dashboard/includes/storage_used.php';
        $prompt = trim(preg_replace('/\s+/u', ' ', (string) ($_POST['prompt'] ?? '')));
        if ($prompt === '' || mb_strlen($prompt) > $soundGenPromptMax) {
            echo json_encode(['success' => false, 'message' => t('alerts_make_sound_err_prompt', ['count' => $soundGenPromptMax])]);
            exit;
        }
        $duration = null; // null = ElevenLabs picks the length
        $durationRaw = (string) ($_POST['duration'] ?? 'auto');
        if ($durationRaw !== 'auto') {
            $duration = round((float) $durationRaw, 1);
            if ($duration < 0.5 || $duration > 30) {
                echo json_encode(['success' => false, 'message' => t('alerts_make_sound_err_duration')]);
                exit;
            }
        }
        $elevenlabs_api_key = '';
        if (is_file('/var/www/config/elevenlabs.php')) {
            include '/var/www/config/elevenlabs.php';
        }
        $elevenKey = trim((string) $elevenlabs_api_key);
        if ($elevenKey === '') {
            echo json_encode(['success' => false, 'message' => t('alerts_make_sound_err_unavailable')]);
            exit;
        }
        if ($max_storage_size - $current_storage_used <= 0) {
            echo json_encode(['success' => false, 'message' => t('alerts_make_sound_err_storage')]);
            exit;
        }
        $soundGenDailyLimit = alerts_sound_gen_limit(!empty($betaAccess), $tier ?? 'None');
        try {
            $db->query("UPDATE generated_sounds SET status = 'failed', error_message = 'alerts_make_sound_err_failed' WHERE " . ALERTS_SOUND_JOB_STALE_SQL);
            // One job at a time per channel.
            $busy = $db->query("SELECT id FROM generated_sounds WHERE status = 'generating' LIMIT 1");
            $busyRow = $busy->fetch_assoc();
            $busy->free();
            if ($busyRow) {
                echo json_encode(['success' => false, 'message' => t('alerts_make_sound_err_busy'), 'job_id' => (int) $busyRow['id']]);
                exit;
            }
            // Reserve the slot before answering so two quick clicks can't both slip under the limit.
            $createdBy = (string) ($_SESSION['username'] ?? '');
            $stmt = $db->prepare("INSERT INTO generated_sounds (prompt, duration_seconds, created_by, status) VALUES (?, ?, ?, 'generating')");
            $stmt->bind_param('sds', $prompt, $duration, $createdBy);
            $stmt->execute();
            $jobId = (int) $stmt->insert_id;
            $stmt->close();
            $used = alerts_sound_gen_used($db);
            if ($used > $soundGenDailyLimit) {
                $del = $db->prepare("DELETE FROM generated_sounds WHERE id = ?");
                $del->bind_param('i', $jobId);
                $del->execute();
                $del->close();
                echo json_encode(['success' => false, 'message' => t('alerts_make_sound_err_limit', ['count' => $soundGenDailyLimit]), 'remaining' => 0]);
                exit;
            }
        } catch (mysqli_sql_exception $e) {
            error_log('alerts.php generate_alert_sound: ' . $e->getMessage());
            echo json_encode(['success' => false, 'message' => t('alerts_make_sound_err_failed')]);
            exit;
        }
        // Answer now, then make the sound in this worker after the response is closed.
        echo json_encode(['success' => true, 'job_id' => $jobId, 'remaining' => max(0, $soundGenDailyLimit - $used)]);
        ignore_user_abort(true);
        @set_time_limit(150);
        if (function_exists('fastcgi_finish_request')) {
            fastcgi_finish_request();
        } else {
            while (ob_get_level() > 0) {
                @ob_end_flush();
            }
            @flush();
        }
        alerts_run_sound_job($db, $jobId, $prompt, $duration, $elevenKey, $media_path, $max_storage_size - $current_storage_used);
        exit;
    }
    if ($action === 'sound_job_status') {
        $jobId = (int) ($_POST['id'] ?? 0);
        try {
            $db->query("UPDATE generated_sounds SET status = 'failed', error_message = 'alerts_make_sound_err_failed' WHERE " . ALERTS_SOUND_JOB_STALE_SQL);
            $stmt = $db->prepare("SELECT status, filename, error_message, TIMESTAMPDIFF(SECOND, created_at, NOW()) AS elapsed FROM generated_sounds WHERE id = ?");
            $stmt->bind_param('i', $jobId);
            $stmt->execute();
            $job = $stmt->get_result()->fetch_assoc();
            $stmt->close();
            if (!$job) {
                echo json_encode(['success' => false, 'status' => 'missing']);
                exit;
            }
            $limit = alerts_sound_gen_limit(!empty($betaAccess), $_SESSION['tier'] ?? 'None');
            echo json_encode([
                'success' => true,
                'status' => $job['status'],
                'filename' => $job['filename'],
                'message' => $job['status'] === 'failed' ? t($job['error_message'] ?: 'alerts_make_sound_err_failed') : '',
                'elapsed' => (int) $job['elapsed'],
                'remaining' => max(0, $limit - alerts_sound_gen_used($db)),
            ]);
        } catch (mysqli_sql_exception $e) {
            error_log('alerts.php sound_job_status: ' . $e->getMessage());
            echo json_encode(['success' => false, 'status' => 'error']);
        }
        exit;
    }
    if ($action === 'remove_alert_media') {
        $id = intval($_POST['id'] ?? 0);
        $field = $_POST['field'] ?? '';
        if (!in_array($field, ['alert_image', 'alert_sound'])) {
            echo json_encode(['success' => false, 'message' => 'Invalid field.']);
            exit;
        }
        $stmt = $db->prepare("UPDATE twitch_alerts SET $field = NULL WHERE id = ?");
        $stmt->bind_param('i', $id);
        $stmt->execute();
        $stmt->close();
        echo json_encode(['success' => true, 'message' => 'Media removed from variant.']);
        exit;
    }
    if ($action === 'set_alert_position') {
        // Drag-to-place coordinates: the box top-left as a 0-100 percentage of the
        // 16:9 canvas. Replaces the old 9-preset string. Clamped server-side.
        $id = intval($_POST['id'] ?? 0);
        if ($id <= 0) {
            echo json_encode(['success' => false, 'message' => 'Invalid position.']);
            exit;
        }
        $position_x = max(0, min(100, floatval($_POST['x'] ?? 0)));
        $position_y = max(0, min(100, floatval($_POST['y'] ?? 0)));
        $stmt = $db->prepare("UPDATE twitch_alerts SET position_x = ?, position_y = ? WHERE id = ?");
        $stmt->bind_param('ddi', $position_x, $position_y, $id);
        $stmt->execute();
        $stmt->close();
        echo json_encode(['success' => true]);
        exit;
    }
    if ($action === 'set_media_levels') {
        // Playback rows only: volume for sound, video, walk-ons and TTS, plus the video's share of the screen.
        $id = intval($_POST['id'] ?? 0);
        $video_size = max(10, min(100, intval($_POST['video_size'] ?? 70)));
        $sound_volume = max(0, min(100, intval($_POST['sound_volume'] ?? 50)));
        $stmt = $db->prepare("UPDATE twitch_alerts SET video_size = ?, sound_volume = ? WHERE id = ? AND alert_category IN ('sound_alerts', 'video_alerts', 'walkons', 'tts')");
        $stmt->bind_param('iii', $video_size, $sound_volume, $id);
        $ok = $stmt->execute();
        $stmt->close();
        echo json_encode(['success' => (bool) $ok]);
        exit;
    }
    echo json_encode(['success' => false, 'message' => 'Unknown action.']);
    exit;
}

